def chapter(doc, title, intro=""):
    if doc.paragraphs and not doc.paragraphs[-1].text.strip():
        p0=doc.paragraphs[-1]._element
        p0.getparent().remove(p0)
    p=heading(doc,title,1); p.paragraph_format.page_break_before=True
    if intro: para(doc,intro)

def add_page_number(section):
    footer=section.footer.paragraphs[0]; footer.alignment=WD_ALIGN_PARAGRAPH.CENTER
    set_run(footer.add_run("总账全科目核对与异常余额管理  "),8,False,"777777")
    fld=OxmlElement("w:fldSimple"); fld.set(qn("w:instr"),"PAGE"); footer._p.append(fld)

def account_matrix(doc, rows):
    table(doc,["科目","业务实质/正常方向","数据来源","月末核对","高频异常","首查路径"],rows,[2.4,3.4,3.3,3.6,3.5,3.5],7.4)

def account_detail(doc, name, essence, sources, normal, checks, abnormalities, path, actions, docs, entries, tax, report, controls):
    heading(doc,name,2)
    table(doc,["检查维度","实务内容"],[
        ["①业务实质",essence],["②数据来源",sources],["③正常余额方向",normal],["④月末核对",checks],
        ["⑤常见异常",abnormalities],["⑥异常原因与⑦排查路径",path],["⑧调整或清理",actions],
        ["⑨支持资料",docs],["⑩典型分录",entries],["⑪税务影响",tax],["⑫报表影响",report],
        ["⑬总账检查点","完成余额构成、发生额、账龄、方向、截止和勾稽检查；所有差异进入台账。"],
        ["⑭主管复核点","复核重大金额、判断依据、审批权限、报表税务影响及未关闭事项。"],
        ["⑮防复发",controls]
    ],[3.4,13.6],8.1)

def add_case_card(doc, no, title, amount, detected, evidence, owner, cause, action, entry, close):
    heading(doc,f"{no} {title}",2)
    table(doc,["步骤","处理"],[
        ["发现异常",detected+f"；涉及金额{amount}万元。"],["查资料",evidence],["沟通责任部门",owner],
        ["定位原因",cause],["调整/业务处理",action],["会计分录",entry],["台账与月结复核",close]
    ],[3.3,13.7],8.3)

