    doc.add_page_break(); heading(doc,"使用说明",1)
    para(doc,"本手册面向具有审计基础、准备承担企业总账或财务主管工作的学习者。它不把核对理解为‘证明余额表加总无误’，而是要求把每个余额追溯到业务事实、责任主体、系统模块、支持单据和外部证据，并把差异处理到可关闭状态。")
    marker(doc,"核心结论","核对的目标是解释余额及其变动并确认权利义务、计量、期间和列报正确。发现差异后先统一口径、识别时间差，再检查系统和真实业务；不得为了对平直接制作调整凭证。",BLUE)
    table(doc,["标识","含义"],[["【会计准则要求】","确认、计量、减值和列报的规范要求"],["【税法要求】","申报、扣除、凭证和税务处理要求"],["【常见实务】","成熟企业常见流程，不等于法定唯一做法"],["【内部政策】","重要性、账龄阈值、审批和关账期限等企业自定规则"],["【总账检查点】","经办必须完成并留痕的核对"],["【财务主管复核点】","对重大判断、异常和关闭证据进行二次复核"]],[4,13])
    heading(doc,"目录",1); add_toc(doc); doc.add_page_break()

    heading(doc,"第1章　从审计找错转向企业主动管账",1)
    para(doc,"审计以获取合理保证为目标，通常按重要性和风险抽样；企业总账对当期账务和关账结果负责，需要组织业务截止、模块对账、调整审批、差异清理和报表解释。审计经验可直接迁移到证据意识、截止测试和异常分析，但企业岗位必须进一步回答谁改、何时改、系统在哪里改、如何防止复发。")
    table(doc,["比较","审计科目检查","企业总账核对"],[["目标","评价报表是否存在重大错报","在关账前形成完整、正确、可解释的账"],["范围","风险导向、重要性和抽样","必查科目全覆盖，重大及异常项目穿透"],["时间","期中、年审集中","日常跟踪，月结、季结、年结递进"],["输出","审计底稿、差异和调整建议","核对底稿、调整凭证、责任台账、关闭证据"],["责任","评价管理层账务","直接组织处理并对结果负责"]],[3,6.8,7.2])
    marker(doc,"岗位转型","不要只提出‘这里可能错了’，要提出可执行处理：事实是什么、数据在哪里、责任人是谁、分录怎么做、税务是否更正、何时关闭。",GREEN)

    heading(doc,"第2章　六类相符与证据层级",1)
    table(doc,["类型","含义","典型核对","解决的问题"],[["账账相符","总账、明细账和子模块记录一致","GL应收=AR客户明细合计","传递和汇总是否完整"],["账证相符","账簿记录有真实、合规且匹配的凭证支持","凭证↔合同、验收、发票、审批","记录是否有依据"],["账实相符","账面资产负债与实物或外部事实一致","库存↔盘点；银行↔对账单","资产是否存在、义务是否真实"],["账表相符","账簿与财务报表项目及附注明细一致","科目余额表↔报表重分类","列报与披露是否正确"],["账税相符","会计账、发票、税务底稿和申报表可调节一致","销项税↔申报表；利润↔纳税调整","纳税数据是否完整正确"],["业财相符","业务台账、模块和财务记录反映同一事实","发货验收↔收入；收货↔存货暂估","业务是否完整进入财务"]],[2.5,4.2,5.3,5.2],8.0)
    marker(doc,"实务提醒","六类相符不能互相替代。GL与AR相等只能说明汇总一致；若销售订单重复，两个系统可能同时错误。",AMBER)

