    heading(doc,"第4章　通用核对方法：余额桥与五个结论",1)
    add_flow(doc,"balance_bridge","任何科目的余额解释",["核对期初","分析本期增加","分析本期减少","重算期末","拆分余额构成","验证权利义务","确定处理结论","留痕并复核"])
    para(doc,"余额桥的最小公式是：期初余额＋本期增加－本期减少＝期末余额。借贷方向不同的科目可改变展示符号，但业务桥接逻辑不变。")
    table(doc,["最终结论","判断标准","动作"],[["余额正确","事实、金额、期间、科目和证据一致","签署底稿并结账"],["合理时间差","事项真实，差异来自可解释的处理时间","列入调节表，设关闭日"],["待处理事项","事实已变化但流程尚未完成","推动业务、模块和审批"],["账务/系统错误","记录与事实或政策不一致","纠错、重跑接口或补录"],["证据不足","无法证明权利义务或金额","升级主管，评估减值、披露、税务与法律行动"]],[3.2,8,6])

