    account_matrix(doc,[["库存现金","备用金及零星现金；通常借方","现金日记账、报销单","总账、盘点记录","负数、超限额、长期白条","突击盘点→最近收支"],["银行存款","银行活期及结算资金；借方","资金模块、银行流水","GL、对账单、调节表","未达、漏户、重复入账","逐账户逐流水勾选"],["其他货币资金","保证金、在途或专项资金；借方","银行、业务台账","对账单、合同、用途","长期不动、错列可用资金","确认权利限制和期限"],["受限资金","因担保、冻结等不可自由使用","银行函证、司法文书","GL、报表披露","未重分类、限制解除未更新","向银行法务确认"]])
    account_detail(doc,"6.1 银行存款与银行余额调节表","企业对银行的存款权利及收付变化。","银行流水、对账单、银企直连、资金模块、GL。","通常借方；贷方一般需解释透支或错账。","逐账户：对账单余额↔银行日记账↔GL；检查账户清单完整、未达项目和受限状态。","银行已扣财务未记、财务已记银行未发生、长期未达、未知来款、注销户余额。","先核对截止日和币种→逐笔勾销→区分银行已达/企业已达→查付款批次、回单和凭证→追长期项目。","企业漏记应补账；真正未达保留调节；错误付款走追回和审批；受限资金重分类/披露。","银行对账单、流水、回单、付款审批、账户清单、银行询证或限制证明。","银行扣手续费0.2万元未入账：借：财务费用0.2；贷：银行存款0.2。","手续费一般需合法凭证；异常损失或罚息另行判断税前扣除。","影响货币资金、财务费用、现金流及受限资金披露。","建立每日接口监控、月末逐账户签署、长期未达分级升级。")

    chapter(doc,"第7章　应收、合同资产及信用减值","应收核对不能只看账龄，还要判断履约、无条件收款权、争议、信用风险和收款核销状态。")
    account_matrix(doc,[["应收账款","已取得无条件收款权；借方","AR、发票、合同、验收","客户明细、收款、对账单","贷方、已收未核销、逾期","客户+单据+核销层追踪"],["应收票据","持有商业汇票权利；借方","票据台账、银行平台","票据实物/电子登记","到期未兑付、背书未转","逐票据核对状态"],["合同资产","履约但收款权仍有条件；借方","项目/验收台账","合同履约和开票条件","错挂应收、长期不转","核对条件是否消除"],["其他应收款","非主营往来、借款押金；借方","借款、押金、代垫台账","员工、合同、回款","员工借款长期挂账","按性质与责任人追踪"],["坏账准备","信用损失抵减；贷方","减值模型、账龄迁徙","应收组合、历史损失","机械按账龄、未更新前瞻信息","复核模型、参数与个案"]])
    account_detail(doc,"7.1 应收账款、合同资产与坏账准备","应收是无条件收款权；合同资产的收款仍取决于时间之外的条件；二者均需按适用准则评估减值。","销售订单、发货签收、验收、开票、AR、收款核销、客户对账和法务争议。","应收和合同资产通常借方，坏账准备贷方。","AR=GL；客户余额=发货验收/开票/收款可调节金额；账龄与到期日、争议和后续回款联动。","应收贷方、收款未核销、合同资产长期不转应收、同客户多编码、超信用期、账龄被滚动凭证重置。","先看客户和合同→穿透未结项目→匹配收款→检查贷项通知/退货→确认履约及开票条件→评估信用风险。","错挂则重分类；已收未核销做核销；无法收回先计提减值，达到核销条件后履行审批并保留追索。","合同、订单、签收验收、发票、银行回单、对账单、催收、诉讼/破产资料、减值模型。","计提坏账10：借：信用减值损失10；贷：坏账准备10。批准核销：借：坏账准备10；贷：应收账款10。后续收回另行恢复并收款。","会计减值不当然等于税前扣除；实际资产损失需按税法留存相应证据并申报。","影响应收/合同资产净额、信用减值损失、利润和所得税差异。","客户主数据治理；收款自动匹配后人工复核；逾期分层催收；重大争议联合法务。")

    chapter(doc,"第8章　预付款项及待摊项目","预付本质是未来取得货物或服务的权利。收货验收后仍挂预付，通常说明核销链断裂、供应商编码不一致或业务存在风险。")
    account_matrix(doc,[["预付款项","预先支付、尚未取得货物服务；借方","采购合同、付款、PO","收货、发票、AP、供应商","长期挂账、贷方、预付应付并存","按供应商及订单串联"],["长期待摊费用","受益超过一年的已付支出；借方","合同、验收、摊销表","受益期、总账、预算","无受益、漏摊、多摊","重新验证未来利益"]])
    account_detail(doc,"8.1 预付款项","尚未取得货物或服务前形成的合同权利，不是付款后的永久停放科目。","采购合同、PO、付款申请、银行回单、收货验收、发票、供应商对账。","通常借方；贷方需排查冲销过度或错挂。","预付明细↔付款↔采购订单↔收货/服务验收↔发票↔AP；同供应商跨科目合并观察。","收货后未冲、发票到未冲、长期预付、供应商失联、同户预付应付并存。","确认是否已履约→核对供应商编码和订单→查模块核销规则→判断退款、资产/费用确认或减值。","已收货按资产/费用和应付处理并核销预付；无法履约评估收回和减值；仅列报口径需要时重分类。","合同、付款审批、回单、进度说明、催收函、供应商确认、法律意见。","支付20：借：预付20；贷：银行20。收货100并取得发票税额13：借：存货100、进项13；贷：预付20、应付93。","长期未取得合规凭证影响所得税扣除；若用途和凭证不满足要求，进项不得抵扣。","影响预付款项、存货/费用、应付和减值损失。","设置30/60/90天催办；采购、AP和业务共同对长期预付签字确认。")

    chapter(doc,"第9章　存货、成本及跌价准备","存货要同时核对数量、单价、金额、所有权、位置和状态。‘总金额一致’不能替代SKU、仓库和批次层面的核对。")
    account_matrix(doc,[["原材料","生产耗用物料；借方","采购、收货、库存","SKU收发存、GL、盘点","负库存、暂估未冲、价差","仓库+订单+移动类型"],["在产品/半成品","生产过程中投入；借方","工单、领料、报工","成本模块、BOM、盘点","长期不动、工单未结","按工单桥接投入产出"],["库存商品","已完工待售；借方","完工入库、销售出库","库存、GL、实物","零成本、负成本、账实差","SKU和批次穿透"],["委托加工物资","外发加工中的物料；借方","外发、加工、收回台账","供应商确认、GL","长期在外、损耗异常","外部对账+在途证明"],["发出商品","已发出但未满足收入条件；借方","出库、物流、验收","销售台账、客户签收","长期不转、已确认收入仍挂","逐订单验证控制权"],["存货跌价准备","存货价值抵减；贷方","库龄、售价、处置成本","呆滞台账、销售预测","漏提、转销错、机械比例","SKU层测算NRV"]])
    account_detail(doc,"9.1 收发存、暂估和成本异常","存货是待售、在产或待耗用资产；成本模块把数量移动转化为金额并归集到产品和期间。","采购收货、库存移动、工单、BOM、报工、完工入库、销售出库、盘点和成本计算。","各存货通常借方，跌价准备贷方。","库存模块金额=GL；期初+入库-出库±调整=期末；数量×有效成本与金额勾稽；实物盘点与系统数量核对。","数量对金额不对、金额对数量不对、负库存、负成本、暂估长期未冲、工单未结、盘盈盘亏、呆滞。","统一仓库/日期/单位→按移动类型重算→查负库存发生点→检查暂估和价差→复核成本卷算→验证盘点差异。","更正业务单据优先；必要时补录/冲销；盘亏按审批转损失；呆滞按可变现净值计提跌价。","收发存、移动明细、工单、BOM、盘点表、采购发票、成本计算表、销售预测。","计提跌价15：借：资产减值损失15；贷：存货跌价准备15。销售已计提存货时按适用政策结转对应准备。","会计跌价准备通常形成税会差异；实际损失税前扣除需符合资产损失规则和证据要求。","影响存货净额、成本、资产减值损失、毛利和所得税。","禁止负库存跨月；暂估逐单关闭；成本计算前冻结关键单据；异常毛利回溯SKU。")

    chapter(doc,"第10章　固定资产、在建工程、无形资产与租赁","长期资产核对的关键不是发票日期，而是资产是否存在、是否达到预定可使用状态、受益期和后续状态是否正确。")
    account_matrix(doc,[["固定资产/累计折旧","长期使用有形资产；原值借、折旧贷","FA卡片、采购验收","GL、实物、折旧表","无卡片、漏提、已报废","卡片→实物→状态"],["在建工程","未达到可使用状态投入；借方","项目台账、合同、验收","工程进度、投产记录","已使用未转固、长期不动","现场和使用部门确认"],["无形资产/累计摊销","可辨认无形资源；资产借、摊销贷","合同、权属、研发资料","权属、受益期、GL","资本化错误、漏摊","确认控制和未来利益"],["使用权资产/租赁负债","租赁使用权和付款义务","租赁合同、付款计划","折旧、利息、付款、GL","重估遗漏、短租错入","合同变更逐项核对"],["长期待摊费用","长期受益支出；借方","合同、验收、摊销表","受益期和实际使用","无受益仍挂、漏摊","重验受益和期限"]])
    account_detail(doc,"10.1 在建工程已使用未转固","在建工程仅承载尚未达到预定可使用状态的投入；达到状态后应按准则转入固定资产并开始折旧。","项目立项、合同、到货安装、验收、试运行、投产记录、付款和工程台账。","在建工程和固定资产借方，累计折旧贷方。","项目台账↔在建工程GL↔现场状态↔验收/投产↔FA卡片↔折旧。","设备已生产但仍挂在建、结算未完成被误认为不能转固、借款费用继续资本化。","取得使用部门书面确认→确定达到可使用状态日→核对归集成本→暂估转固→补提折旧→后续结算调成本。","转固并补提折旧；重大跨年错误按差错准则评估追溯或当期处理。","验收、投产、试运行、项目决算、采购合同、付款、现场照片、资产卡片。","转固260：借：固定资产260；贷：在建工程260。补提当月折旧2：借：制造费用/管理费用2；贷：累计折旧2。","折旧税前扣除起点和计税基础可能与会计不同，形成税会差异；发票未到不当然阻止会计转固。","资产类别重分类；折旧影响利润、成本和递延所得税。","工程项目设置预计投产日；业务验收自动触发转固任务；月末复核长期不动项目。")

    chapter(doc,"第11章　其他资产和特殊余额","低频科目也必须按经济实质、权利义务和计量基础设计核对程序，不能因不常发生而忽略。")
